{
  "cvars": {
    "ivs": [
      {
        "description": "Applicant gender. Binary indicator where 1 = female, 0 = male. Primary independent variable to test whether being female affects the probability that a mortgage application is accepted.",
        "columns": [
          "female"
        ]
      }
    ],
    "dv": {
      "description": "Mortgage application outcome. Binary dependent variable where 1 = application accepted, 0 = application denied.",
      "columns": [
        "accept"
      ]
    },
    "controls": [
      {
        "description": "Applicant race (Black vs. other). Binary control to adjust for observed racial differences in approval rates.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "black"
        ]
      },
      {
        "description": "Applicant mortgage credit rating (z-scored). Ordinal credit rating standardized to mean 0 / sd 1 to aid interpretation and model convergence.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "mortgage_credit_z"
        ]
      },
      {
        "description": "Applicant consumer credit rating (z-scored). Ordinal consumer credit standardized to mean 0 / sd 1.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "consumer_credit_z"
        ]
      },
      {
        "description": "Debt-payment-to-income ratio (PI_ratio, z-scored). Continuous control representing debt burden standardized to mean 0 / sd 1.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PI_ratio_z"
        ]
      },
      {
        "description": "Loan-to-value ratio (z-scored). Continuous control representing loan size relative to property value standardized to mean 0 / sd 1.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "loan_to_value_z"
        ]
      },
      {
        "description": "Housing expense (housing_expense_ratio, z-scored). Continuous control representing housing expense as ratio of income, standardized to mean 0 / sd 1.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "housing_expense_ratio_z"
        ]
      },
      {
        "description": "History of bad credit. Binary control where 1 = has bad credit history, 0 = no bad credit history.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "bad_history"
        ]
      },
      {
        "description": "Marital status. Binary control where 1 = married, 0 = not married.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "married"
        ]
      },
      {
        "description": "Self-employment indicator. Binary control where 1 = self-employed, 0 = not self-employed.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "self_employed"
        ]
      },
      {
        "description": "Private mortgage insurance denial indicator. Binary control where 1 = denied PMI, 0 = not denied PMI.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "denied_PMI"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform the raw dataset into the analysis-ready dataframe. The function:\n      - Keeps only rows with non-missing values for the variables used in the model.\n      - Ensures binary columns are integers (0/1).\n      - Standardizes continuous/ordinal predictors to z-scores to aid interpretation and numerical stability.\n    The returned dataframe contains the original binary indicators plus the *_z standardized columns used in the model.\n    \"\"\"\n    df = df.copy()\n\n    # Columns required for the analysis\n    required_cols = [\n        'female', 'accept', 'black', 'mortgage_credit', 'consumer_credit',\n        'PI_ratio', 'loan_to_value', 'housing_expense_ratio',\n        'bad_history', 'married', 'self_employed', 'denied_PMI'\n    ]\n\n    # Coerce to numeric where possible (will convert problematic strings to NaN)\n    for col in required_cols:\n        # keep original types if already numeric, otherwise coerce\n        df[col] = pd.to_numeric(df[col], errors='coerce')\n\n    # Drop rows with missing data in any required column\n    df = df.dropna(subset=required_cols).reset_index(drop=True)\n\n    # Ensure binary indicator columns are integer 0/1\n    binary_cols = ['female', 'accept', 'black', 'bad_history', 'married', 'self_employed', 'denied_PMI']\n    for col in binary_cols:\n        # round then convert to int to handle floats like 0.0/1.0\n        df[col] = df[col].round().astype(int)\n\n    # Create standardized (z-scored) versions of continuous / ordinal predictors\n    z_cols = ['mortgage_credit', 'consumer_credit', 'PI_ratio', 'loan_to_value', 'housing_expense_ratio']\n    for col in z_cols:\n        mean = df[col].mean()\n        std = df[col].std(ddof=0)\n        if std == 0 or np.isnan(std):\n            # if constant (unexpected), create zeros\n            df[col + '_z'] = 0.0\n        else:\n            df[col + '_z'] = (df[col] - mean) / std\n\n    # Final check: keep only the columns we will use in the model + originals for traceability\n    # (model uses standardized columns where applicable)\n    keep_cols = [\n        'female', 'accept', 'black', 'mortgage_credit_z', 'consumer_credit_z',\n        'PI_ratio_z', 'loan_to_value_z', 'housing_expense_ratio_z',\n        'bad_history', 'married', 'self_employed', 'denied_PMI'\n    ]\n\n    # Confirm all keep_cols exist; if some z-columns are missing due to earlier naming, raise error\n    missing = [c for c in keep_cols if c not in df.columns]\n    if len(missing) > 0:\n        raise ValueError(f\"Missing expected transformed columns: {missing}\")\n\n    # Return dataframe containing at least the variables needed for modeling\n    return df[keep_cols].copy()\n",
  "m_code": "def model(df: pd.DataFrame) -> dict:\n    \"\"\"\n    Fit a logistic regression (binary outcome: accept) to estimate the effect of gender (female)\n    on the probability of mortgage application acceptance adjusting for observed controls.\n\n    Returns a dictionary with the fitted statsmodels result object and a table of odds ratios\n    with 95% confidence intervals and p-values.\n    \"\"\"\n    # Features included in the model (must match the transformed dataframe column names)\n    features = [\n        'female', 'black', 'mortgage_credit_z', 'consumer_credit_z', 'PI_ratio_z',\n        'loan_to_value_z', 'housing_expense_ratio_z', 'bad_history', 'married',\n        'self_employed', 'denied_PMI'\n    ]\n\n    # Ensure all features are present\n    missing = [f for f in features + ['accept'] if f not in df.columns]\n    if missing:\n        raise ValueError(f\"Missing columns required for modeling: {missing}\")\n\n    X = df[features]\n    X = sm.add_constant(X, has_constant='add')\n    y = df['accept']\n\n    # Fit logistic regression using statsmodels Logit\n    logit_model = sm.Logit(y, X)\n    results = logit_model.fit(disp=False)\n\n    # Compute odds ratios and 95% confidence intervals\n    params = results.params\n    conf = results.conf_int()\n    or_table = pd.DataFrame({\n        'OR': np.exp(params),\n        'CI_lower': np.exp(conf[0]),\n        'CI_upper': np.exp(conf[1]),\n        'p_value': results.pvalues\n    })\n\n    # Print summary for quick inspection (can be removed if used in non-interactive pipelines)\n    print(results.summary())\n    print('\\nOdds ratios (exp(coef)) with 95% CI:\\n')\n    print(or_table)\n\n    return {'model_result': results, 'odds_ratios': or_table}\n"
}
